# Fixes after the 10 pregen-reviewer reports of 06.11 (prereview_*_2026-11-06.md). Executed by make_remaining_scripts.py before the writers.
import re
def rep(k, f, old, new):
    assert old in P[k][f], (k, f, old[:60])
    P[k][f] = P[k][f].replace(old, new)
def sub_all(pat, new, fields=("clip",)):
    for k in P:
        for f in fields:
            P[k][f] = re.sub(pat, new, P[k][f])
# ---- global: thumb 15/20, numbered focus event, no damping sentence, glass in end
sub_all(r"covering the lower (right|left) 20 percent of the frame width \(never more than 25 percent\)", r"covering the lower \1 15 percent of the frame width (never more than 20 percent)")
sub_all(r"the focus hunts: the picture goes soft for half a second and snaps back sharp", "the whole picture blurs for 0.5 s, then snaps sharp")
sub_all(r"the focus hunts for half a second and (then )?snaps back sharp", "the whole picture blurs for 0.5 s, then snaps sharp")
sub_all(r"the focus hunts for half a second", "the whole picture blurs for 0.5 s, then snaps sharp")
sub_all(r"; the (king|room) and (the room|Marcel|the king) (are|stay) in the same place in both frames\.", ".")
sub_all(r"the king and the room are in the same place in both frames\. ", "")
sub_all(r"; the king and the room are in the same place in both frames", "")
for k in P: P[k]["end"] = P[k]["end"].replace("No text, no logos, no modern objects,", "No text, no logos, no modern objects, no glass or crystal glass anywhere,")

